#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.13881637, -0.292828765, -0.026042679999999995], 'basis': [[0.0, 0.7504886003129299, 0.6608833942537364], [-0.9796537660207747, 0.13263601865352576, -0.15061933898757726], [-0.20069503910488953, -0.6474369060812654, 0.7352189836522217]], 'axis': [0.6608833942537364, -0.15061933898757726, 0.7352189836522217], 'zmin': -0.0723020767250158, 'zmax': 0.07459837212843518, 'profiles': [{'outer': [[-0.1395451220261161, 0.05765729734816409], [-0.1470032205530613, 0.06677222127666654], [-0.15044849742519334, 0.07767789458225097], [-0.1506838759594885, 0.07902711717071124], [-0.14902703163229614, 0.0897732533083735], [-0.14346767546930073, 0.09955214304366077], [-0.13476226144793912, 0.10674918769218435], [-0.12233376338078798, 0.11113588540507043], [-0.11118559341121166, 0.1093984153895291], [-0.1011486192706309, 0.10334956615414585], [-0.10045604698922646, 0.10250319666356902], [-0.09381210082703788, 0.10730820677628324], [-0.08742497785709971, 0.10903556168396782], [-0.0772887080259086, 0.11103803948956117], [-0.061551958145193916, 0.10395752774940052], [-0.0024094760500817753, 0.07073239763321174], [0.006207577929156165, 0.06532490429275799], [0.008781991728821865, 0.058981964147835665], [0.010984258084372733, 0.044174006126489036], [0.010901687980479769, 0.04348333325560798], [0.02010525863693365, 0.039818350651322755], [0.03063322023843968, 0.030530016142865667], [0.03344158061943589, 0.024932131850793654], [0.0407306460845095, 0.03270787709786269], [0.04450297702132505, 0.039163867114176916], [0.046280020765128334, 0.0413125943360806], [0.05534958630198532, 0.04933804968556994], [0.07365503226587083, 0.05057155362078174], [0.10786755113340268, 0.04247373799294712], [0.11512313782027596, 0.047124856223087354], [0.11634839867255331, 0.047822848246430336], [0.13373350127140274, 0.04548918421069173], [0.13661925642206554, 0.034339260719597815], [0.13689746186738516, 0.02577347705771613], [0.13680748518486935, 0.01124728074699358], [0.14000721623418044, -0.008156211195391665], [0.14878864108354492, -0.03084240822660042], [0.14869051448255616, -0.03172088904910314], [0.14844798003400175, -0.032293590548842524], [0.14311128440011867, -0.05502738525024196], [0.14141564291160721, -0.05603334279977144], [0.1408824874628816, -0.05829101114220175], [0.12088865586673665, -0.07006652307021145], [0.11375130201777689, -0.0698623898677605], [0.09909296540723245, -0.07406278157869704], [0.0839899130713792, -0.08242428755663113], [0.07276397825368228, -0.090722962444457], [0.06644721936372228, -0.09409160436579497], [0.058398267669322296, -0.10038505706045742], [0.04607796261324748, -0.09380537601052806], [0.04703628325069156, -0.09196096655650217], [0.05139284114874725, -0.08521428300048971], [0.02345138121514277, -0.06941145295612824], [0.0060270272488386414, -0.06407620690669727], [0.0002472727691547389, -0.06584676119429517], [-0.02153387597135165, -0.061513941361871875], [-0.041874579858215064, -0.052992205162461614], [-0.05324836457934921, -0.04590693088599058], [-0.05791937336806279, -0.04279838918691787], [-0.06227312695226446, -0.037849338553753116], [-0.06107875655016374, -0.031196599212465537], [-0.056583924284730934, -0.02938954010671733], [-0.053907135363511306, -0.03053161739370536], [-0.050997634999104216, -0.031975111027414876], [-0.037345806699276514, -0.03391087763097466], [-0.023872661681499645, -0.03176934250903804], [-0.012367499585537695, -0.025845473855826112], [-0.010043919390638636, -0.024053784511704285], [-0.016987902750270765, -0.021289216770667262], [-0.026864223680187253, -0.012575752337509453], [-0.028675709226893324, -0.013443701420691678], [-0.03800443453730101, -0.01615278566176898], [-0.05020395208364578, -0.013075515977527626], [-0.11296501617595095, 0.02377260138288309], [-0.12784764131471232, 0.036287296517820554], [-0.13485384426221889, 0.050504874482458384], [-0.13406821706179245, 0.05435660493157009]], 'holes': []}], 'simplify_tolerance': 5.98945034086067e-05, 'sketch_entity_count': 101}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
